def _esc(s):
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("'", "\\'").replace('"', "&quot;")

def _strings_xml(idx):
    rows = ['<?xml version="1.0" encoding="utf-8"?>', '<resources>']
    for k, vals in STRINGS.items():
        rows.append(f'    <string name="{k}">{_esc(vals[idx])}</string>')
    rows.append('</resources>')
    return "\n".join(rows)

add("app/src/main/res/values/strings.xml", _strings_xml(0))
add("app/src/main/res/values-uk/strings.xml", _strings_xml(1))
add("app/src/main/res/values-ru/strings.xml", _strings_xml(2))

